import sys, json, re, datetime, posixpath, urllib.parse

# THE INDEX OF A GRAPH SPACE (graph-space, GH #945). One graph space per
# knowledge space: the nodes of every source of the space and the edges
# between them, resolved here once so that a cross question (`in_graph`, cell
# `./query`) never wakes a source.
#
# A SOURCE ANNOUNCES, THE INDEX PULLS. A node source (a file space: `fh-`;
# reserved: `ob-`) emits `source_changed` {source, version, path, fmt, parser,
# mark, nodes, links, tomb} after every move of a head. The index records the
# announced version (`sources.announced`) and sends exactly three requests on
# `pull`: ONE `outline` (limit = the announced node count), ONE `links` (limit
# = the announced link count) and ONE `near` {k}. A constant number of hops per
# source, whatever its size; a large answer travels as one blob, which the
# substrate resolves on delivery (AGENTS.md invariant 14). Each answer comes
# back on `in_pulled` and is parked in `pulls`; the bundle whose insert
# completes the set of three goes on -- and only if the version it pulled is
# still the announced one. A stale pull is dropped, never written (gh945
# `a_stale_pull_never_overwrites`).
#
# WRITE FIRST, RESOLVE SECOND. Phase 1 (one bundle) replaces the source's
# nodes, names and outgoing edges (each `unresolved` unless it points into the
# source itself or out of the space) and its `inferred` edges, and reads back
# what phase 2 needs AFTER those writes. Phase 2 (one bundle) resolves: the
# source's own edges, foreign `unresolved`/`broken` edges whose target the
# source now provides, and foreign edges into the source (anchor still there:
# `resolved`; gone: `broken` with `since`). Every phase-2 update names the
# state it read in its `where` -- a compare-and-set. Two sources that name each
# other and are indexed at the same time (one workspace commit of a package)
# resolved against the old store under "read, then write" and both stayed
# `unresolved`; written first, the later phase 1 always sees the earlier one,
# and a phase 2 that read an older state than another phase 2 already wrote
# changes nothing.
#
# A `tomb` drops the source's nodes, names and outgoing edges and turns every
# resolved edge into it `broken` -- in one bundle, no pull. A removal carries
# no version (the file space sends `{source, path, tomb: true}`), so none is
# asked of it.
#
# BROKEN MEANS LOST. An edge is `broken` only when it pointed somewhere once
# (a `to_addr` in the store, or in the source's own rows before phase 1
# replaced them) and that target is gone; a target that was never there --
# an imported constant, a re-export the extractor has no node for -- stays
# `unresolved`. Markdown is the exception by its nature: the file is there
# and the anchor is not, and the anchor is all the link says.
#
# RESOLUTION IS A PURE FUNCTION per edge kind (`target_of`, `resolve`): python
# `import`/`call` (exact, from the `ast` extractor), rust `use`, markdown
# `link`/`url`. A `near` neighbour is an edge of class `inferred`, never
# `extracted` (R-BC-1, condition 2).
#
# No model, no embedding request, no network: `near` is answered from bits the
# source already stored.
doc = json.load(sys.stdin)
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
P = doc.get("params") or {}
header = envelope.get("header") or {}
hop = header.get("hop") or {}
ctx = header.get("context") or {}


def _int(key, default):
    v = P.get(key, default)
    if v is None or (isinstance(v, str) and not v.strip()):
        return default
    try:
        return int(float(v))
    except Exception:
        return default


NEAR_K = max(1, min(20, _int("near_k", 5)))
NODES_CAP = max(1, _int("nodes_cap", 5000))
LINKS_CAP = max(1, _int("links_cap", 5000))
SCAN = max(100, _int("scan_max", 20000))

ME = "index"
FMT = "%Y-%m-%dT%H:%M:%S.%fZ"
PARTS = ("outline", "links", "near")
CHUNK = 400
SOURCE_RE = re.compile(r"^(fh|ob)-[0-9a-f]{12}$")
VERSION_RE = re.compile(r"^[0-9a-f]{4,64}$")
SCHEME_RE = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*:")
IDENT_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")
PY_EXT = (".py", ".pyi")
RS_EXT = (".rs",)
MD_EXT = (".md", ".markdown")
# Kinds whose node may be a resolution target by name (python, rust), in the
# order a tie is broken: an `impl` block names a type it does not define.
ITEM_ORDER = ("class", "def", "fn", "struct", "enum", "trait", "type", "const",
              "static", "union", "macro", "mod", "impl")


# ============================================================ PURE: NAMES

def v12(v):
    return str(v or "")[:12]


def truthy(v):
    return v is True or (isinstance(v, (int, float)) and v != 0) or \
        (isinstance(v, str) and v.strip().lower() in ("1", "true", "yes"))


def lang_of(fmt, path):
    """`python`, `rust`, `markdown` or the format as announced. A source that
    does not name its format is read by its extension."""
    f = str(fmt or "").strip().lower()
    if f in ("py", "python"):
        return "python"
    if f in ("rs", "rust"):
        return "rust"
    if f in ("md", "markdown"):
        return "markdown"
    if f:
        return f
    p = str(path or "").lower()
    if p.endswith(PY_EXT):
        return "python"
    if p.endswith(RS_EXT):
        return "rust"
    if p.endswith(MD_EXT):
        return "markdown"
    return "text"


def module_of(path, lang):
    """The name a source answers to. python: the path without `.py`, `/` ->
    `.`, `__init__` = its package; rust: the path under the nearest `src/` as
    `crate::a::b` (`lib.rs`, `main.rs`, `mod.rs` name their directory);
    everything else: the path itself."""
    p = str(path or "")
    segs = [s for s in p.split("/") if s]
    if lang == "python" and segs:
        last = segs[-1]
        for ext in PY_EXT:
            if last.endswith(ext):
                last = last[:-len(ext)]
                break
        segs = segs[:-1] + ([] if last == "__init__" else [last])
        return ".".join(segs)
    if lang == "rust" and segs:
        if "src" in segs[:-1]:
            i = len(segs) - 1 - segs[::-1].index("src", 1)
            rest = segs[i + 1:]
        else:
            rest = segs[:]
        if rest and rest[-1].endswith(".rs"):
            rest[-1] = rest[-1][:-3]
        if rest and rest[-1] in ("lib", "main") and len(rest) == 1:
            rest = []
        elif rest and rest[-1] == "mod":
            rest = rest[:-1]
        return "::".join(["crate"] + rest)
    return p


def crate_dir(path):
    """The directory that holds a rust source's nearest `src/`, '' if none."""
    segs = [s for s in str(path or "").split("/") if s]
    if "src" not in segs[:-1]:
        return ""
    i = len(segs) - 1 - segs[::-1].index("src", 1)
    return "/" + "/".join(segs[:i])


def package_of(module, path):
    """The package a python source sits in: itself for an `__init__`."""
    base = str(path or "").rsplit("/", 1)[-1]
    if base in ("__init__.py", "__init__.pyi"):
        return module
    return module.rsplit(".", 1)[0] if "." in module else ""


def ident(anchor):
    """The last identifier of an anchor: `class:A/def:b` -> `b`, `sec:intro`
    -> `intro`, a duplicate's `~2` dropped."""
    a = str(anchor or "").rsplit("/", 1)[-1]
    a = a.split("~", 1)[0]
    return a.split(":", 1)[1] if ":" in a else a


def kind_of(anchor):
    a = str(anchor or "").rsplit("/", 1)[-1]
    return a.split(":", 1)[0] if ":" in a else ""


def qualified(module, anchor, lang):
    """`<module>:<A.b>` (python and the rest), `crate::a::A::b` (rust)."""
    parts = [ident(seg) for seg in str(anchor or "").split("/") if seg]
    if lang == "rust":
        return "::".join([module] + parts)
    return module + ":" + ".".join(parts)


def top_items(anchors):
    """ident -> the top-level anchor that carries it (no `/`), ties broken by
    `ITEM_ORDER`, then by the anchor itself."""
    best = {}
    for a in sorted(set(anchors)):
        if "/" in a or "~" in a:
            continue
        k = kind_of(a)
        rank = ITEM_ORDER.index(k) if k in ITEM_ORDER else len(ITEM_ORDER)
        name = ident(a)
        if name not in best or rank < best[name][0]:
            best[name] = (rank, a)
    return {n: a for n, (r, a) in best.items()}


def clean_nodes(raw):
    """The announced outline as `[{anchor, kind, name, oneline, parser}]`,
    one per anchor, in anchor order."""
    out = {}
    for n in raw if isinstance(raw, list) else []:
        if not isinstance(n, dict):
            continue
        a = str(n.get("anchor") or "").strip()
        if not a or len(a) > 512 or a in out:
            continue
        out[a] = {"anchor": a, "kind": str(n.get("kind") or kind_of(a)),
                  "name": str(n.get("name") or ident(a)),
                  "oneline": str(n.get("oneline") or n.get("summary") or "")[:300],
                  "parser": str(n.get("parser") or "")}
    return [out[a] for a in sorted(out)]


def clean_links(raw):
    """The announced edges as `[{kind, from_anchor, target_name, alias}]`,
    deduplicated on (from_anchor, kind, target_name)."""
    seen = {}
    for e in raw if isinstance(raw, list) else []:
        if not isinstance(e, dict):
            continue
        kind = str(e.get("kind") or "").strip()
        target = str(e.get("target_name") or e.get("target") or "").strip()
        if not kind or not target or len(target) > 1024:
            continue
        # `alias`: the name `import ... as x` binds, exact from `ast` (the
        # file space's import edge, OR-BC-55); absent when nothing is renamed.
        alias = str(e.get("alias") or "").strip()
        frm = str(e.get("from_anchor") or e.get("from") or "").strip()
        key = (frm, kind, target)
        if key not in seen:
            seen[key] = {"kind": kind, "from_anchor": frm, "target_name": target,
                         "alias": alias}
    return [seen[k] for k in sorted(seen)]


def clean_near(raw, source):
    """`near` neighbours as `[{addr, source, score}]`, the source itself left
    out, best first."""
    out = {}
    for n in raw if isinstance(raw, list) else []:
        if not isinstance(n, dict):
            continue
        addr = str(n.get("addr") or n.get("file") or n.get("source") or "").strip()
        anchor = str(n.get("anchor") or "").strip()
        if "@" in addr:
            base, rest = addr.split("@", 1)
            addr = base + ("#" + rest.split("#", 1)[1] if "#" in rest else "")
        if anchor and "#" not in addr:
            addr = addr + "#" + anchor
        src = addr.split("#", 1)[0]
        if not SOURCE_RE.match(src) or src == source:
            continue
        score = n.get("score")
        if score is None and n.get("distance") is not None:
            try:
                score = 1.0 / (1.0 + float(n.get("distance")))
            except Exception:
                score = None
        try:
            score = round(float(score), 6)
        except Exception:
            score = 0.0
        if addr not in out or score > out[addr]["score"]:
            out[addr] = {"addr": addr, "source": src, "score": score}
    return sorted(out.values(), key=lambda r: (-r["score"], r["addr"]))


# ============================================================ PURE: TARGETS

def md_slug(text):
    """The heading slug of the file space's markdown extractor, verbatim:
    lower case, punctuation but `-`/`_` dropped, every whitespace a `-`. A
    link's `#frag` is slugged with it, so `#Setup` finds the anchor of the
    heading `Setup` (`sec:setup`)."""
    s = re.sub(r"[^\w\s-]", "", str(text).strip().lower())
    return re.sub(r"\s", "-", s)


def frag_member(frag):
    """A link fragment -> the section anchor it names, '' for none. The
    fragment is URL-decoded first (`#Getting%20Started`)."""
    slug = md_slug(urllib.parse.unquote(str(frag or "")))
    return ("sec:" + slug) if slug else ""


def py_absolute(target, src):
    """A python import target made absolute: `.x:y` against the package of
    the importing source. -> (module, member) or None."""
    t = target
    member = ""
    if ":" in t:
        t, member = t.split(":", 1)
    if t.startswith("."):
        dots = len(t) - len(t.lstrip("."))
        rest = t[dots:]
        pkg = package_of(src["module"], src["path"])
        segs = pkg.split(".") if pkg else []
        up = dots - 1
        if up > len(segs):
            return None
        base = segs[:len(segs) - up] if up else segs
        t = ".".join(base + ([rest] if rest else []))
    if not t:
        return None
    return t, member


def py_aliases(links, src):
    """What a python source's imports bind: name -> (module, member). `from
    a.b import c as d` binds `d` -> (a.b, c); `import a.b as x` binds `x` ->
    (a.b, ''); `import a.b` binds `a` -> (a, '')."""
    out = {}
    for e in links:
        if e["kind"] != "import":
            continue
        ab = py_absolute(e["target_name"], src)
        if not ab:
            continue
        mod, member = ab
        if member:
            out[e["alias"] or member] = (mod, member)
        elif e["alias"]:
            out[e["alias"]] = (mod, "")
        else:
            out.setdefault(mod.split(".", 1)[0], (mod.split(".", 1)[0], ""))
            out.setdefault(mod, (mod, ""))
    return out


def target_of(e, src, links, own_anchors):
    """One extracted edge -> where it points before any lookup:
    `{to_module, to_member, state}` with `state` `external` for a target out
    of the space, `self` for one inside the same source, else `open`."""
    kind, t, lang = e["kind"], e["target_name"], src["lang"]
    if kind == "url" or (kind == "link" and SCHEME_RE.match(t) and not t.startswith("/")):
        return {"to_module": "", "to_member": "", "state": "external"}
    if kind == "link":
        path, frag = (t.split("#", 1) + [""])[:2]
        if not path:
            path = src["path"]
        elif not path.startswith("/"):
            path = posixpath.join(posixpath.dirname(src["path"]) or "/", path)
        path = posixpath.normpath(path)
        if path.startswith("//"):
            path = "/" + path.lstrip("/")
        member = frag_member(frag)
        state = "self" if path == src["path"] else "open"
        return {"to_module": path, "to_member": member, "state": state}
    if lang == "python" and kind == "import":
        ab = py_absolute(t, src)
        if not ab:
            return {"to_module": "", "to_member": "", "state": "open"}
        mod, member = ab
        state = "self" if mod == src["module"] else "open"
        return {"to_module": mod, "to_member": member, "state": state}
    if lang == "python" and kind == "call":
        aliases = py_aliases(links, src)
        tops = top_items(own_anchors)
        if ":" in t:
            ab = py_absolute(t, src)
            if not ab:
                return {"to_module": "", "to_member": t, "state": "open"}
            mod, member = ab
            head = mod.split(".", 1)[0]
            if head in aliases and aliases[head][1] == "" and mod not in aliases:
                mod = aliases[head][0] + mod[len(head):]
            state = "self" if mod == src["module"] else "open"
            return {"to_module": mod, "to_member": member, "state": state}
        if "." not in t:
            if t in tops:
                return {"to_module": src["module"], "to_member": t, "state": "self"}
            if t in aliases:
                mod, member = aliases[t]
                if member:
                    return {"to_module": mod, "to_member": member, "state": "open"}
                return {"to_module": mod, "to_member": "", "state": "open"}
            return {"to_module": "", "to_member": t, "state": "open"}
        head, rest = t.split(".", 1)
        if head in aliases:
            mod, member = aliases[head]
            full = ".".join([x for x in (mod, member, rest) if x])
        else:
            full = t
        mod, member = full.rsplit(".", 1)
        state = "self" if mod == src["module"] else "open"
        return {"to_module": mod, "to_member": member, "state": state}
    if lang == "rust" and kind in ("import", "use"):
        p = t.split(" as ", 1)[0].strip().rstrip(";")
        segs = [s for s in p.split("::") if s]
        if not segs or "{" in p:
            return {"to_module": "", "to_member": "", "state": "open"}
        if segs[0] in ("self", "super"):
            base = src["module"].split("::")
            while segs and segs[0] in ("self", "super"):
                if segs[0] == "super":
                    if len(base) <= 1:
                        return {"to_module": "", "to_member": "", "state": "open"}
                    base = base[:-1]
                segs = segs[1:]
            segs = base + segs
        if segs[0] != "crate":
            return {"to_module": "", "to_member": "", "state": "external"}
        if segs[-1] == "*":
            return {"to_module": "::".join(segs[:-1]), "to_member": "", "state": "open"}
        if len(segs) == 1:
            return {"to_module": "crate", "to_member": "", "state": "open"}
        mod, member = "::".join(segs[:-1]), segs[-1]
        state = "self" if mod == src["module"] else "open"
        return {"to_module": mod, "to_member": member, "state": state}
    return {"to_module": "", "to_member": "", "state": "open"}


def provided(module, path, lang):
    """The `to_module` values an edge elsewhere may carry and this source may
    now satisfy: its module, every dotted suffix of it and of its parent
    (python's suffix rule and `a.b:c` read as module `a.b.c`), and its path."""
    out = {module, path}
    if lang == "python" and module:
        segs = module.split(".")
        for i in range(len(segs)):
            out.add(".".join(segs[i:]))
        for i in range(len(segs) - 1):
            out.add(".".join(segs[i:-1]))
    if lang == "rust" and "::" in module:
        out.add(module.rsplit("::", 1)[0])
    return sorted(x for x in out if x)


# ============================================================ PURE: RESOLVE

def resolve(edge, sources, nodes_of):
    """One edge -> {state, to_addr, to_source}, or None when the answer needs
    the nodes of a source `nodes_of` does not know. `edge`: {kind, lang,
    from_source, to_module, to_member}; `sources`: [{source, path, module,
    lang, tomb}]; `nodes_of(source)` -> its anchors, or None.

    import/call (python): the module by exact name, else by a unique dotted
    suffix (two candidates: `unresolved`); a member -> its top-level node,
    else the module `<module>.<member>`, else `unresolved`. use (rust): the
    module `crate::a::b` (two crates: the one the edge's source sits in);
    `::*` -> the source; a member -> its top-level node, else the module of
    that name, else `unresolved`. link: the path -> the source, `#frag` ->
    `sec:<slug>` (`broken` when the file is there and the anchor is not), no
    file -> `unresolved`. Whether an unresolved edge is `broken` -- it had a
    target once -- is phase 2's question, not this function's."""
    # A source counts once it is indexed: announced but not yet written, its
    # nodes are unknown, and reading "no node" there would break an edge that
    # its own phase 2 is about to resolve (measured in the interleaving lock).
    live = [s for s in sources if not truthy(s.get("tomb")) and s.get("version")]
    lang = edge.get("lang") or ""
    mod, member = edge.get("to_module") or "", edge.get("to_member") or ""
    none = {"state": "unresolved", "to_addr": "", "to_source": ""}
    if not mod:
        return none

    def at(src_id, anchors_member):
        anchors = nodes_of(src_id)
        if anchors is None:
            return None
        if anchors_member.startswith("sec:"):
            return src_id + "#" + anchors_member if anchors_member in anchors else ""
        hit = top_items(anchors).get(anchors_member)
        return src_id + "#" + hit if hit else ""

    if edge.get("kind") == "link":
        hits = [s for s in live if s.get("path") == mod]
        if len(hits) != 1:
            return none
        sid = hits[0]["source"]
        if not member:
            return {"state": "resolved", "to_addr": sid, "to_source": sid}
        got = at(sid, member)
        if got is None:
            return None
        if got:
            return {"state": "resolved", "to_addr": got, "to_source": sid}
        return {"state": "broken", "to_addr": sid + "#" + member, "to_source": sid}

    def modules(name):
        if lang == "rust":
            hits = [s for s in live if s.get("lang") == "rust" and s.get("module") == name]
            if len(hits) > 1:
                me = [s for s in sources if s.get("source") == edge.get("from_source")]
                home = crate_dir(me[0].get("path")) if me else ""
                hits = [s for s in hits if crate_dir(s.get("path")) == home]
            return hits
        exact = [s for s in live if s.get("lang") == lang and s.get("module") == name]
        if exact or lang != "python":
            return exact
        return [s for s in live if s.get("lang") == "python"
                and str(s.get("module") or "").endswith("." + name)]

    sep = "::" if lang == "rust" else "."
    hits = modules(mod)
    if len(hits) > 1:
        return none
    if not hits:
        if member:
            sub = modules(mod + sep + member)
            if len(sub) == 1:
                sid = sub[0]["source"]
                return {"state": "resolved", "to_addr": sid, "to_source": sid}
        return none
    sid = hits[0]["source"]
    if not member:
        return {"state": "resolved", "to_addr": sid, "to_source": sid}
    got = at(sid, member)
    if got is None:
        return None
    if got:
        return {"state": "resolved", "to_addr": got, "to_source": sid}
    sub = modules(mod + sep + member)
    if len(sub) == 1:
        s2 = sub[0]["source"]
        return {"state": "resolved", "to_addr": s2, "to_source": s2}
    # The module is there, the member is no node of it and no submodule: an
    # imported constant, a re-export -- never found, so not `broken`
    # (OR-BC-55 (4); a member that WAS found and is gone breaks in phase 2).
    return none


# ============================================================ PURE: PHASES

def now():
    return datetime.datetime.now(datetime.timezone.utc).strftime(FMT)


def sel(table, columns, where, limit, order=None):
    a = {"operation": "select", "table": table, "columns": columns, "where": where,
         "limit": int(limit)}
    if order:
        a["order_by"] = [{"col": c, "dir": o} for c, o in order]
    return a


def chunks(xs, n=CHUNK):
    xs = list(xs)
    return [xs[i:i + n] for i in range(0, len(xs), n)] or []


PREV_COLS = ["from_addr", "kind", "target_name", "state", "to_addr", "to_source", "since"]
EDGE_COLS = ["from_addr", "from_source", "kind", "lang", "target_name", "to_module",
             "to_member", "to_addr", "to_source", "state", "class", "score", "since"]


def phase1_ops(src, nodes, links, near, stamp):
    """Phase 1 of one source, pure: the writes, then the reads phase 2 needs,
    as `[(id, op)]`. `src`: {source, version, path, lang, module}."""
    S = src["source"]
    anchors = [n["anchor"] for n in nodes]
    own = set(anchors)
    # What the source's edges pointed at before they are replaced: phase 2
    # tells a lost target (`broken`) from one never found (`unresolved`).
    ops = [("r-prev", sel("edges", PREV_COLS, {"from_source": S, "class": "extracted",
                                                "state": {"in": ["resolved", "broken"]}}, SCAN)),
           ("n-del", {"operation": "delete", "table": "nodes", "where": {"source": S}}),
           ("m-del", {"operation": "delete", "table": "names", "where": {"source": S}}),
           ("e-del", {"operation": "delete", "table": "edges", "where": {"from_source": S}})]
    for i, n in enumerate(nodes):
        ops.append(("n%d" % i, {"operation": "insert", "table": "nodes", "row": {
            "addr": S + "#" + n["anchor"], "source": S, "anchor": n["anchor"],
            "kind": n["kind"], "name": n["name"], "oneline": n["oneline"],
            "parser": n["parser"]}}))
    names = [(src["module"], S, "module")] + \
        [(qualified(src["module"], a, src["lang"]), S + "#" + a, "qualified") for a in anchors]
    seen = set()
    for i, (name, addr, kind) in enumerate(names):
        if not name or (name, addr) in seen:
            continue
        seen.add((name, addr))
        ops.append(("m%d" % i, {"operation": "insert", "table": "names", "row": {
            "name": name, "addr": addr, "source": S, "kind": kind}}))
    members = set()
    for i, e in enumerate(links):
        t = target_of(e, src, links, anchors)
        frm = S + ("#" + e["from_anchor"] if e["from_anchor"] else "")
        row = {"from_addr": frm, "from_source": S, "kind": e["kind"], "lang": src["lang"],
               "target_name": e["target_name"], "to_module": t["to_module"],
               "to_member": t["to_member"], "to_addr": "", "to_source": "",
               "state": "unresolved", "class": "extracted", "score": "", "since": ""}
        if t["state"] == "external":
            row["state"] = "external"
        elif t["state"] == "self":
            got = resolve(dict(row), [dict(src, tomb="")], lambda s: anchors if s == S else None)
            if got and got["state"] != "unresolved":
                row.update(got)
                if got["state"] == "broken":
                    row["since"] = stamp
        if row["state"] == "unresolved" and t["to_member"]:
            members.add(ident(t["to_member"]))
        ops.append(("e%d" % i, {"operation": "insert", "table": "edges", "row": row}))
    for i, n in enumerate(near):
        ops.append(("i%d" % i, {"operation": "insert", "table": "edges", "row": {
            "from_addr": S, "from_source": S, "kind": "similar", "lang": src["lang"],
            "target_name": n["addr"], "to_module": "", "to_member": "",
            "to_addr": n["addr"], "to_source": n["source"], "state": "resolved",
            "class": "inferred", "score": "%.6f" % n["score"], "since": ""}}))
    ops.append(("s-upd", {"operation": "update", "table": "sources",
                          "set": {"version": src["version"], "indexed_at": stamp, "tomb": "",
                                  "module": src["module"], "lang": src["lang"]},
                          "where": {"source": S}}))
    ops.append(("p-drop", {"operation": "delete", "table": "pulls",
                           "where": {"source": S, "version": src["version"]}}))
    # The reads of phase 2 -- after the writes above, in the same bundle.
    ops.append(("r-src", sel("sources", ["source", "path", "module", "lang", "tomb",
                                         "announced", "version"], {}, SCAN)))
    ops.append(("r-anch", sel("nodes", ["anchor"], {"source": S}, SCAN)))
    ops.append(("r-own", sel("edges", EDGE_COLS, {"from_source": S, "state": "unresolved"},
                             SCAN)))
    for j, part in enumerate(chunks(sorted(members))):
        ops.append(("r-nodes%d" % j, sel("nodes", ["source", "anchor", "name"],
                                         {"name": {"in": part}}, SCAN)))
    ops.append(("r-into", sel("edges", EDGE_COLS, {"to_source": S}, SCAN)))
    for j, part in enumerate(chunks(provided(src["module"], src["path"], src["lang"]))):
        ops.append(("r-open%d" % j, sel("edges", EDGE_COLS, {
            "to_module": {"in": part}, "state": {"in": ["unresolved", "broken"]}}, SCAN)))
    return ops


def phase2_ops(S, own_anchors, rows, stamp):
    """Phase 2 of source `S`, pure: the compare-and-set updates of every edge
    whose state the store now decides differently. `rows`: the reads of phase
    1 by leg id prefix (`r-prev`, `r-src`, `r-own`, `r-nodes`, `r-into`,
    `r-open`)."""
    sources = [dict(s, lang=s.get("lang") or "") for s in rows.get("r-src", [])]
    prev = {(str(r.get("from_addr") or ""), str(r.get("kind") or ""),
             str(r.get("target_name") or "")): r for r in rows.get("r-prev", [])}
    known = {S: list(own_anchors)}
    for r in rows.get("r-nodes", []):
        known.setdefault(str(r.get("source") or ""), []).append(str(r.get("anchor") or ""))

    def nodes_of_all(sid):
        return known.get(sid, [])

    def nodes_of_s(sid):
        return list(own_anchors) if sid == S else None

    plan = {}
    for e in rows.get("r-own", []):
        plan[(e["from_addr"], e["kind"], e["target_name"])] = (e, resolve(e, sources, nodes_of_all))
    for key in ("r-into", "r-open"):
        for e in rows.get(key, []):
            if e.get("from_source") == S or e.get("class") != "extracted":
                continue
            k = (e["from_addr"], e["kind"], e["target_name"])
            if k in plan:
                continue
            got = resolve(e, sources, nodes_of_s)
            if got is None and key == "r-into":
                # Its target was in S and is no node of S now.
                got = {"state": "broken", "to_addr": e.get("to_addr") or "",
                       "to_source": S}
            plan[k] = (e, got)
    ops = []
    for i, k in enumerate(sorted(plan)):
        e, got = plan[k]
        if got is None:
            continue
        # The target this edge had: its own row's, or -- for the source's own
        # edges, rewritten `unresolved` by phase 1 -- the row before that.
        had = {"to_addr": str(e.get("to_addr") or ""),
               "to_source": str(e.get("to_source") or ""),
               "since": str(e.get("since") or "") if e.get("state") == "broken" else ""}
        p = prev.get(k) if e.get("from_source") == S else None
        if not had["to_addr"] and p and p.get("to_addr"):
            had = {"to_addr": str(p.get("to_addr") or ""),
                   "to_source": str(p.get("to_source") or ""),
                   "since": str(p.get("since") or "") if p.get("state") == "broken" else ""}
        if got["state"] == "unresolved" and had["to_addr"]:
            # Lost, not never found (OR-BC-55 (4)).
            got = {"state": "broken", "to_addr": had["to_addr"],
                   "to_source": had["to_source"] or got["to_source"]}
        old = str(e.get("state") or "")
        if got["state"] == "unresolved" and old == "unresolved":
            continue
        if got["state"] == old and got["to_addr"] == (e.get("to_addr") or ""):
            continue
        if got["state"] == "unresolved" and old == "broken" and e.get("to_source") != S:
            continue
        if got["state"] == "broken":
            if old == "broken":
                continue
            # A broken edge keeps the address it had: `callers` of the old
            # node still counts it (gh945 `a_rename_breaks_and_reports_the_edge`),
            # and the time it broke, when indexing its own source again.
            since = had["since"] or stamp
            to_addr = e.get("to_addr") or got["to_addr"] or ""
        else:
            since, to_addr = "", got["to_addr"]
        ops.append(("u%d" % i, {"operation": "update", "table": "edges",
                                "set": {"state": got["state"], "to_addr": to_addr,
                                        "to_source": got["to_source"], "since": since},
                                "where": {"from_addr": e["from_addr"], "kind": e["kind"],
                                          "target_name": e["target_name"], "state": old,
                                          "to_addr": e.get("to_addr") or ""}}))
    return ops


def tomb_ops(S, version, stamp):
    """A removed source, in one bundle: its rows go, every resolved edge into
    it breaks (`since` set), the source row stays with `tomb`."""
    return [("s-upd", {"operation": "update", "table": "sources",
                       "set": {"announced": version, "version": version, "tomb": "1",
                               "indexed_at": stamp}, "where": {"source": S}}),
            ("n-del", {"operation": "delete", "table": "nodes", "where": {"source": S}}),
            ("m-del", {"operation": "delete", "table": "names", "where": {"source": S}}),
            ("e-del", {"operation": "delete", "table": "edges", "where": {"from_source": S}}),
            ("p-drop", {"operation": "delete", "table": "pulls", "where": {"source": S}}),
            ("e-brk", {"operation": "update", "table": "edges",
                       "set": {"state": "broken", "since": stamp},
                       "where": {"to_source": S, "state": "resolved"}})]


def pull_requests(S, version, nodes, links):
    """The three requests of one announcement, as (hop, body)."""
    file = S + "@" + version
    asks = (("outline", {"version": version, "limit": max(1, min(nodes, NODES_CAP))}),
            ("links", {"version": version, "limit": max(1, min(links, LINKS_CAP))}),
            ("near", {"version": version, "k": NEAR_K}))
    out = []
    for part, args in asks:
        op_id = "gs:%s:%s:%s" % (part, S, version)
        out.append(({"route": "pull", "op": part, "op_id": op_id},
                    {"op": part, "file": file, "source": S, "version": version,
                     "args": args, "messages": []}))
    return out


# ============================================================ PLUMBING

def emit(msgs):
    for m in msgs:
        if isinstance(m, dict) and not any(k in m for k in ("messages", "system", "attachments")):
            m["messages"] = []
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def park(reason=""):
    if reason:
        sys.stderr.write("graph-space/index: %s\n" % reason)
    emit([])


def store(ops, phase, carry):
    return {"header": {"route": "index_store", "phase": phase, "reply_cell": ME,
                       "cur_call": json.dumps(carry, sort_keys=True)},
            "messages": [{"origin": "assistant", "type": "tool_call", "id": cid,
                          "text": json.dumps(args)} for cid, args in ops]}


def legs(body):
    out = {}
    for m in body.get("messages") or []:
        if not isinstance(m, dict):
            continue
        try:
            payload = json.loads(m.get("text") or "null")
        except Exception:
            payload = None
        out[str(m.get("id") or "")] = {"payload": payload, "error_code": ""}
    results = body.get("results")
    if isinstance(results, list):
        for r in results:
            if isinstance(r, dict):
                leg = out.setdefault(str(r.get("tool_call_id") or ""),
                                     {"payload": None, "error_code": ""})
                leg["error_code"] = str(r.get("error_code") or "")
    elif len(out) == 1:
        next(iter(out.values()))["error_code"] = str(hop.get("error_code") or "")
    return out


def rows_by_prefix(lg, prefix):
    out = []
    for cid in sorted(lg):
        if cid == prefix or (cid.startswith(prefix) and cid[len(prefix):].isdigit()):
            p = lg[cid]["payload"]
            if isinstance(p, list):
                out.extend(r for r in p if isinstance(r, dict))
    return out


def loads(v, default):
    if isinstance(v, str):
        try:
            return json.loads(v)
        except Exception:
            return default
    return default if v is None else v


# ============================================================ LANES

lane = str(hop.get("route") or "")
phase = str(ctx.get("cur_phase") or "")
op_ = str(hop.get("operation") or "")

if lane == "source_changed":
    S = str(d.get("source") or "").strip()
    version = str(d.get("version") or "").strip().lower()
    if not SOURCE_RE.match(S):
        park("source_changed without a source address -- dropped")
    stamp = now()
    if truthy(d.get("tomb")):
        # A removal names no version (file space: `{source, path, tomb}`); an
        # empty `announced` also turns every pull still in flight stale.
        version = v12(version) if VERSION_RE.match(version) else ""
        emit([store(tomb_ops(S, version, stamp), "tomb", {"source": S, "version": version})])
    if not VERSION_RE.match(version):
        park("source_changed without a version -- dropped")
    version = v12(version)
    path = str(d.get("path") or "")
    lang = lang_of(d.get("fmt"), path)
    try:
        n_nodes = int(d.get("nodes") or 0)
        n_links = int(d.get("links") or 0)
    except Exception:
        n_nodes, n_links = 0, 0
    row = {"source": S, "path": path, "lang": lang, "module": module_of(path, lang),
           "version": "", "announced": version, "indexed_at": "", "tomb": ""}
    ops = [("s-ins", {"operation": "insert", "table": "sources", "row": row}),
           ("s-upd", {"operation": "update", "table": "sources",
                      "set": {"announced": version, "path": path, "lang": lang,
                              "module": row["module"]},
                      "where": {"source": S}}),
           ("p-old", {"operation": "delete", "table": "pulls",
                      "where": {"source": S, "version": {"neq": version}}})]
    msgs = [store(ops, "announce", {"source": S, "version": version})]
    for h, b in pull_requests(S, version, n_nodes, n_links):
        b["header"] = h
        msgs.append(b)
    emit(msgs)

if lane == "in_pulled":
    op_id = str(hop.get("op_id") or "")
    bits = op_id.split(":")
    if len(bits) != 4 or bits[0] != "gs" or bits[1] not in PARTS \
            or not SOURCE_RE.match(bits[2]) or not VERSION_RE.match(bits[3]):
        park("in_pulled under a foreign op_id %r -- dropped" % op_id)
    part, S, version = bits[1], bits[2], bits[3]
    keep = {k: d.get(k) for k in ("ok", "error", "nodes", "links", "near", "neighbors",
                                  "items", "hits", "next", "version", "truncated")
            if k in d}
    ok = "1" if d.get("ok") is True else ""
    ops = [("p-ins", {"operation": "insert", "table": "pulls", "row": {
               "source": S, "version": version, "part": part, "ok": ok,
               "body": json.dumps(keep, sort_keys=True), "at": now()}}),
           ("p-all", sel("pulls", ["part", "ok", "body"], {"source": S, "version": version},
                         10)),
           ("s-row", sel("sources", ["source", "path", "lang", "module", "announced"],
                         {"source": S}, 1))]
    emit([store(ops, "pulled", {"source": S, "version": version, "part": part})])

if lane:
    park("unknown lane %r -- dropped" % lane)
if not op_:
    park("a message with neither a lane nor a store answer -- dropped")

carry = loads(ctx.get("cur_call"), {})
if not isinstance(carry, dict):
    carry = {}
lg = legs(d)

if phase in ("announce", "tomb", "done"):
    # `s-ins` meets the unique index on a known source; nothing else may fail.
    bad = sorted(c for c, leg in lg.items() if leg["error_code"] and c != "s-ins")
    if bad:
        sys.stderr.write("graph-space/index: store refused %s in phase %s\n"
                         % (", ".join(bad), phase))
    emit([])

if phase == "pulled":
    if lg.get("p-ins", {}).get("error_code"):
        # The same part twice (an announcement repeated): the first one counts.
        emit([])
    S, version = str(carry.get("source") or ""), str(carry.get("version") or "")
    got = {}
    for r in (lg.get("p-all") or {}).get("payload") or []:
        if isinstance(r, dict) and r.get("part") in PARTS:
            got[r["part"]] = r
    if any(p not in got for p in PARTS):
        emit([])
    srow = ((lg.get("s-row") or {}).get("payload") or [None])[0]
    if not isinstance(srow, dict) or v12(srow.get("announced")) != v12(version):
        # A stale pull: a newer version is announced. Dropped, never written.
        emit([store([("p-drop", {"operation": "delete", "table": "pulls",
                                 "where": {"source": S, "version": version}})],
                    "done", carry)])
    body = {p: loads(got[p].get("body"), {}) for p in PARTS}
    if not got["outline"].get("ok") or not got["links"].get("ok"):
        sys.stderr.write("graph-space/index: %s@%s not readable (%s) -- left as it was\n"
                         % (S, version, json.dumps(body["outline"].get("error")
                                                   or body["links"].get("error"))))
        emit([store([("p-drop", {"operation": "delete", "table": "pulls",
                                 "where": {"source": S, "version": version}})],
                    "done", carry)])
    nodes = clean_nodes(body["outline"].get("nodes") or body["outline"].get("items"))
    links = clean_links(body["links"].get("links") or body["links"].get("items"))
    nb = body["near"] if got["near"].get("ok") else {}
    near = clean_near(nb.get("near") or nb.get("neighbors") or nb.get("hits")
                      or nb.get("items"), S)[:NEAR_K]
    lang = srow.get("lang") or lang_of("", srow.get("path"))
    src = {"source": S, "version": version, "path": str(srow.get("path") or ""),
           "lang": lang, "module": srow.get("module") or module_of(srow.get("path"), lang)}
    stamp = now()
    emit([store(phase1_ops(src, nodes, links, near, stamp), "p1",
                {"source": S, "version": version})])

if phase == "p1":
    bad = sorted(c for c, leg in lg.items() if leg["error_code"])
    if bad:
        sys.stderr.write("graph-space/index: store refused %s in phase p1\n" % ", ".join(bad))
    S = str(carry.get("source") or "")
    rows = {k: rows_by_prefix(lg, k)
            for k in ("r-prev", "r-src", "r-own", "r-nodes", "r-into", "r-open")}
    anchors = [str(r.get("anchor") or "") for r in rows_by_prefix(lg, "r-anch")]
    ops = phase2_ops(S, anchors, rows, now())
    if not ops:
        emit([])
    emit([store(ops, "done", {"source": S, "version": carry.get("version")})])

park("unknown phase %r -- dropped" % phase)
